// pybytes.mjs
// Reproduces CPython's repr() for `bytes` objects, so that printing a built
// byte sequence yields exactly what Python's `print(b'...')` would produce.

/**
 * Format an array of byte values (0-255) exactly like Python's bytes repr.
 *
 * Rules (matching CPython Objects/bytesobject.c):
 *  - Quote with single quotes by default; switch to double quotes when the
 *    data contains a single quote but no double quote.
 *  - Escape the active quote char and backslash with a backslash.
 *  - \t, \n, \r get their short escapes.
 *  - Bytes outside the printable ASCII range 0x20..0x7e become \xhh
 *    (lowercase hex).
 *
 * @param {number[]} bytes
 * @returns {string}
 */
export function pythonBytesRepr(bytes) {
  const hasSingle = bytes.includes(0x27); // '
  const hasDouble = bytes.includes(0x22); // "
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
  const quoteChar = String.fromCharCode(quote);

  let out = 'b' + quoteChar;
  for (const b of bytes) {
    if (b === quote || b === 0x5c) {
      out += '\\' + String.fromCharCode(b);
    } else if (b === 0x09) {
      out += '\\t';
    } else if (b === 0x0a) {
      out += '\\n';
    } else if (b === 0x0d) {
      out += '\\r';
    } else if (b >= 0x20 && b < 0x7f) {
      out += String.fromCharCode(b);
    } else {
      out += '\\x' + b.toString(16).padStart(2, '0');
    }
  }
  return out + quoteChar;
}

/**
 * Encode a string to UTF-8 bytes as a plain number array,
 * mirroring Python's str.encode() (UTF-8 by default).
 *
 * @param {string} s
 * @returns {number[]}
 */
export function utf8Encode(s) {
  return Array.from(Buffer.from(s, 'utf8'));
}

// construct.mjs
// Minimal black-box reimplementation of the `construct` library builders used
// by the source script: Int8ul, Int16ul and Bytes(n). Each builder takes a
// value and returns the encoded bytes as a plain array of integers (0-255),
// little-endian where applicable — matching `construct.X.build(value)`.

/**
 * Error mirroring construct.core.FormatFieldError raised when a value does
 * not fit the target struct format.
 */
export class FormatFieldError extends Error {
  constructor(structFormat, value, requirement) {
    super(
      'Error in path (building)\n' +
        `struct '${structFormat}' error during building, given value ${value}\n` +
        `struct.error: '${structFormat.slice(1)}' format requires ${requirement}`
    );
    this.name = 'FormatFieldError';
    this.structFormat = structFormat;
    this.value = value;
  }
}

/** construct.Int8ul.build(value): unsigned 8-bit integer -> 1 byte. */
export function buildInt8ul(value) {
  if (!Number.isInteger(value) || value < 0 || value > 255) {
    throw new FormatFieldError('<B', value, '0 <= number <= 255');
  }
  return [value & 0xff];
}

/** construct.Int16ul.build(value): unsigned 16-bit little-endian -> 2 bytes. */
export function buildInt16ul(value) {
  if (!Number.isInteger(value) || value < 0 || value > 65535) {
    throw new FormatFieldError('<H', value, '0 <= number <= 65535');
  }
  return [value & 0xff, (value >> 8) & 0xff];
}

/**
 * construct.Bytes(n).build(data): fixed-length byte field.
 * `data` must be an array of exactly `n` byte values.
 */
export function buildBytes(length, data) {
  if (!Array.isArray(data) || data.length !== length) {
    throw new Error(`Bytes field expected ${length} bytes, got ${data ? data.length : 0}`);
  }
  return data.slice();
}

// argparse.mjs
// Minimal black-box reimplementation of the subset of Python's argparse used
// by the source script: required optional arguments with type=int / type=str,
// auto -h/--help, "--opt value" and "--opt=value" forms, unambiguous prefix
// abbreviation, negative numbers as values, and argparse-compatible usage /
// error / help formatting (exit code 2 on parse errors, 0 after help).

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** repr() of a short string, the way argparse embeds raw values in errors. */
function strRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const q = hasSingle && !hasDouble ? '"' : "'";
  let out = q;
  for (const ch of s) {
    if (ch === q || ch === '\\') out += '\\' + ch;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else out += ch;
  }
  return out + q;
}

/** Terminal width like shutil.get_terminal_size(): COLUMNS env, tty, else 80. */
function terminalWidth() {
  const env = Number(process.env.COLUMNS);
  if (Number.isInteger(env) && env > 0) return env;
  if (process.stdout.columns) return process.stdout.columns;
  return 80;
}

/** Faithful port of argparse.HelpFormatter._get_lines part splitting. */
function getLines(parts, indent, prefix, textWidth) {
  const lines = [];
  let line = [];
  let lineLen = (prefix != null ? prefix.length : indent.length) - 1;
  for (const part of parts) {
    if (lineLen + 1 + part.length > textWidth && line.length > 0) {
      lines.push(indent + line.join(' '));
      line = [];
      lineLen = indent.length - 1;
    }
    line.push(part);
    lineLen += 1 + part.length;
  }
  if (line.length > 0) lines.push(indent + line.join(' '));
  if (prefix != null && lines.length > 0) {
    lines[0] = lines[0].slice(indent.length);
  }
  return lines;
}

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
    // -h/--help is always first, exactly like argparse.
    this.actions = [
      { optionStrings: ['-h', '--help'], dest: 'help', type: 'help', required: false },
    ];
  }

  addArgument(name, { type = 'str', required = false } = {}) {
    const dest = name.replace(/^--?/, '');
    this.actions.push({ optionStrings: [name], dest, type, required });
  }

  /** usage parts, e.g. ['[-h]', '--a A', '--b B', ...] */
  _formatActionInvocationParts() {
    return this.actions.map((a) => {
      if (a.type === 'help') return '[-h]';
      return `${a.optionStrings[0]} ${a.dest.toUpperCase()}`;
    });
  }

  formatUsage() {
    const prefix = 'usage: ';
    const textWidth = Math.max(terminalWidth() - 2, 11);
    const parts = this._formatActionInvocationParts();
    const usage = [this.prog, ...parts].join(' ');
    if (prefix.length + usage.length <= textWidth) {
      return prefix + usage;
    }
    let indent;
    let lines;
    if (prefix.length + this.prog.length <= 0.75 * textWidth) {
      indent = ' '.repeat(prefix.length + this.prog.length + 1);
      lines = getLines([this.prog, ...parts], indent, prefix, textWidth);
    } else {
      indent = ' '.repeat(prefix.length);
      lines = getLines(parts, indent, prefix, textWidth);
    }
    return prefix + lines.join('\n');
  }

  formatHelp() {
    const indent = '  ';
    const invocations = this.actions.map((a) => {
      if (a.type === 'help') return '-h, --help';
      return `${a.optionStrings[0]} ${a.dest.toUpperCase()}`;
    });
    const actionMaxLength =
      Math.max(...invocations.map((s) => s.length)) + indent.length;
    const helpPosition = Math.min(actionMaxLength + 2, 24);
    const lines = ['options:'];
    this.actions.forEach((a, i) => {
      if (a.type === 'help') {
        lines.push(
          indent + invocations[i].padEnd(helpPosition - indent.length) +
            'show this help message and exit'
        );
      } else {
        lines.push(indent + invocations[i]);
      }
    });
    return this.formatUsage() + '\n\n' + lines.join('\n') + '\n';
  }

  error(message) {
    process.stderr.write(this.formatUsage() + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  _convert(action, raw) {
    if (action.type === 'int') {
      // Mirrors Python's int(str): optional sign, decimal digits, single
      // underscores allowed between digits, surrounding whitespace ok.
      const trimmed = raw.replace(/^[\t\n\v\f\r ]+|[\t\n\v\f\r ]+$/g, '');
      if (/^[+-]?\d(?:_?\d)*$/.test(trimmed)) {
        return parseInt(trimmed.replace(/_/g, ''), 10);
      }
      this.error(`argument ${action.optionStrings[0]}: invalid int value: ${strRepr(raw)}`);
    }
    return raw;
  }

  parseArgs(argv) {
    const values = {};
    for (const a of this.actions) {
      if (a.type !== 'help') values[a.dest] = undefined;
    }
    const extras = [];
    const seen = new Set();

    let i = 0;
    while (i < argv.length) {
      const token = argv[i];
      const isOptionLike =
        token.length > 1 && token.startsWith('-') && !NEGATIVE_NUMBER.test(token);

      if (!isOptionLike) {
        extras.push(token); // no positionals are defined
        i += 1;
        continue;
      }

      // Split --name=value form.
      let name = token;
      let inlineValue = null;
      const eq = token.indexOf('=');
      if (token.startsWith('--') && eq !== -1) {
        name = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }

      // Exact match, then unambiguous prefix abbreviation (allow_abbrev).
      let action = this.actions.find((a) => a.optionStrings.includes(name));
      if (!action && name.startsWith('--')) {
        const matches = this.actions.filter((a) =>
          a.optionStrings.some((o) => o.startsWith('--') && o.startsWith(name))
        );
        if (matches.length === 1) {
          action = matches[0];
        } else if (matches.length > 1) {
          const all = matches.flatMap((a) => a.optionStrings.filter((o) => o.startsWith(name)));
          this.error(`ambiguous option: ${name} could match ${all.join(', ')}`);
        }
      }
      if (!action) {
        extras.push(token);
        i += 1;
        continue;
      }

      if (action.type === 'help') {
        process.stdout.write(this.formatHelp());
        process.exit(0);
      }

      let raw;
      if (inlineValue != null) {
        raw = inlineValue;
        i += 1;
      } else if (
        i + 1 < argv.length &&
        (argv[i + 1] === '-' ||
          !argv[i + 1].startsWith('-') ||
          NEGATIVE_NUMBER.test(argv[i + 1]))
      ) {
        raw = argv[i + 1];
        i += 2;
      } else {
        this.error(`argument ${action.optionStrings[0]}: expected one argument`);
      }

      values[action.dest] = this._convert(action, raw);
      seen.add(action.dest);
    }

    const missing = this.actions.filter(
      (a) => a.required && !seen.has(a.dest)
    );
    if (missing.length > 0) {
      this.error(
        'the following arguments are required: ' +
          missing.map((a) => a.optionStrings[0]).join(', ')
      );
    }
    if (extras.length > 0) {
      this.error('unrecognized arguments: ' + extras.join(' '));
    }
    return values;
  }
}

// test19.mjs
// Node.js (ESM) port of test19.py — builds binary fields with the local
// `construct` reimplementation and prints each result using Python's bytes
// repr, byte-for-byte identical to the original script's output.

import { basename } from 'node:path';
import { ArgumentParser } from './lib/argparse.mjs';
import { buildInt8ul, buildInt16ul, buildBytes, FormatFieldError } from './lib/construct.mjs';
import { pythonBytesRepr, utf8Encode } from './lib/pybytes.mjs';

function main() {
  const parser = new ArgumentParser(basename(process.argv[1]));
  parser.addArgument('--a', { type: 'int', required: true });
  parser.addArgument('--b', { type: 'int', required: true });
  parser.addArgument('--c', { type: 'int', required: true });
  parser.addArgument('--d', { type: 'str', required: true });
  parser.addArgument('--e', { type: 'int', required: true });
  parser.addArgument('--f', { type: 'int', required: true });
  parser.addArgument('--g', { type: 'int', required: true });
  parser.addArgument('--h', { type: 'str', required: true });
  parser.addArgument('--i', { type: 'int', required: true });
  const args = parser.parseArgs(process.argv.slice(2));

  try {
    const result1 = buildInt8ul(args.a); // 构建第一个字段
    const result2 = buildInt16ul(args.b); // 构建第二个字段
    const result3 = buildInt8ul(args.c); // 构建第三个字段
    const result4 = buildBytes(utf8Encode(args.d).length, utf8Encode(args.d)); // 构建字符串数据，使用实际长度
    const result5 = buildInt8ul(args.f); // 构建第五个字段
    const result6 = buildInt8ul(args.g); // 构建第六个字段
    const result7 = buildInt8ul(args.i); // 构建第七个字段
    const result8 = buildBytes(utf8Encode(args.h).length, utf8Encode(args.h)); // 构建第二个字符串数据，使用实际长度
    const result9 = buildInt8ul(((args.a + args.b + args.c) % 256 + 256) % 256); // 构建校验字段，确保在字节范围内
    const results = [
      result1, result2, result3, result4, result5,
      result6, result7, result8, result9,
    ];
    for (const r of results) {
      console.log(pythonBytesRepr(r));
    }
  } catch (err) {
    if (err instanceof FormatFieldError) {
      // construct.core.FormatFieldError: uncaught in the original script,
      // which aborts with a traceback on stderr and exit code 1.
      process.stderr.write(`construct.core.FormatFieldError: ${err.message}\n`);
      process.exit(1);
    }
    throw err;
  }
}

main();

